import { chromium } from '@playwright/test';
const b = await chromium.launch({ executablePath: 'C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe' }).catch(()=>chromium.launch());
const pg = await b.newPage({ viewport: { width: 390, height: 844 } });
await pg.goto('http://127.0.0.1:8095/#/pages/inspection/index?kind=pre', { waitUntil: 'domcontentloaded', timeout: 30000 });
await pg.waitForTimeout(2500);
const info = await pg.evaluate(() => {
  const el = document.querySelector('.field-input.date-input');
  const icon = document.querySelector('.date-icon');
  if(!el) return {el:false};
  const r = el.getBoundingClientRect();
  const ir = icon ? icon.getBoundingClientRect() : null;
  const cs = icon ? getComputedStyle(icon.querySelector('div')||icon) : null;
  return { elBox:[r.x,r.y,r.width,r.height], iconBox: ir?[ir.x,ir.y,ir.width,ir.height]:null, bg: cs?cs.backgroundImage:null };
});
console.log(JSON.stringify(info));
await pg.screenshot({ path: 'C:/Users/Administrator/AppData/Local/Temp/insp_pw.png' });
await b.close();
console.log('done');

